"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper


def _upper():
    return Upper()


def _strip():
    return Strip()


def _squeeze():
    return Squeeze()


STEPS = {"upper": _upper, "strip": _strip, "squeeze": _squeeze}

# Steps that accept a length argument are tracked separately.
_LENGTH_STEPS = {"truncate": Truncate}


def lookup(name: str):
    if ":" in name:
        parts = name.split(":", 1)
        key = parts[0]
        arg_str = parts[1]
        if key in _LENGTH_STEPS:
            if not arg_str:
                raise ValueError(f"step {key!r} requires a length argument, got empty value")
            try:
                length = int(arg_str)
            except ValueError:
                raise ValueError(f"step {key!r} expects an integer length, got {arg_str!r}")
            return _LENGTH_STEPS[key](length)
        # Colon but not a known length step → fall through to regular lookup (KeyError)
        if key not in STEPS:
            raise KeyError(f"no step named {key!r}. Known: {', '.join(sorted(STEPS))}")
        return STEPS[key]()
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]()

